def test_basic(): assert column_average("a,b\n1,2\n2,4\n4,5", "b") == 3.67
def test_missing():
    for args in [("a\n1", "z"), ("a", "a")]:
        try:
            column_average(*args); assert False
        except ValueError:
            pass
